// Parse and clean NewsAPI results into structured format
const inputData = $input.first().json;
const formData = $('Form Trigger').first().json;

try {
  // Extract articles from NewsAPI response
  const articles = inputData.articles || [];

  if (articles.length === 0) {
    return [{
      json: {
        error: true,
        message: 'No articles found for this industry/niche. Try different keywords.',
        industry: formData['Industry/Niche']
      }
    }];
  }

  // Format articles for summarization
  const formattedArticles = articles.map((article, index) => ({
    position: index + 1,
    title: article.title || 'No title',
    source: article.source?.name || 'Unknown source',
    description: article.description || '',
    content: article.content || article.description || '',
    url: article.url || '',
    publishedAt: article.publishedAt || '',
    author: article.author || 'Unknown'
  }));

  return [{
    json: {
      industry: formData['Industry/Niche'],
      keywords: formData['Keywords (Optional)'] || '',
      tone: formData['Newsletter Tone'],
      totalArticles: formattedArticles.length,
      articles: formattedArticles,
      articlesText: formattedArticles.map(a => 
        `Article ${a.position}: ${a.title}\nSource: ${a.source}\nContent: ${a.content}\nURL: ${a.url}`
      ).join('\n\n---\n\n')
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      message: 'Failed to parse news results: ' + error.message,
      rawResponse: inputData
    }
  }];
}

// Parse OpenAI summaries response
const inputData = $input.first().json.output[0].content[0].text;
const previousData = $('Parse News Results').first().json;

try {
  // Parse the message content (it's a JSON string)
  let summariesData;

  if (typeof inputData.message?.content === 'string') {
    summariesData = JSON.parse(inputData.message.content);
  } else if (inputData.message?.content) {
    summariesData = inputData.message.content;
  } else {
    throw new Error('No content in OpenAI response');
  }

  return [{
    json: {
      industry: previousData.industry,
      tone: previousData.tone,
      summaries: summariesData.summaries || [],
      summariesText: (summariesData.summaries || []).map(s => 
        `## ${s.hook}\n\n${s.summary}\n\n**Why it matters:** ${s.whyItMatters}\n\n🔗 Source: ${s.source} - ${s.url}`
      ).join('\n\n---\n\n')
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      message: 'Failed to parse summaries: ' + error.message,
      rawResponse: inputData
    }
  }];
}

// Compile final newsletter content for Google Doc
const inputData = $input.first().json;
const summariesData = $('Parse Summaries').first().json;

try {
  // Parse intro content
  let introData;

  if (typeof inputData.message?.content === 'string') {
    introData = JSON.parse(inputData.message.content);
  } else if (inputData.message?.content) {
    introData = inputData.message.content;
  } else {
    throw new Error('No content in OpenAI response');
  }

  // Get current date for the newsletter
  const today = new Date();
  const dateString = today.toLocaleDateString('en-US', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });

  // Compile the full newsletter
  const newsletterContent = `# ${summariesData.industry} Weekly News Digest

**Date:** ${dateString}

**Subject Line:** ${introData.subjectLine}

---

## 👋 Hello!

${introData.greeting}

${introData.preview}

---

# 📰 This Week's Top Stories

${summariesData.summariesText}

---

## 📬 That's a Wrap!

Thanks for reading this week's ${summariesData.industry} digest. Hit reply if you have any thoughts or tips for next week's edition!

Until next time,
[Your Name]

---
*This newsletter was curated with AI assistance.*`;

  return [{
    json: {
      documentTitle: `${summariesData.industry} Weekly News - ${dateString}`,
      subjectLine: introData.subjectLine,
      content: newsletterContent,
      industry: summariesData.industry
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      message: 'Failed to compile newsletter: ' + error.message,
      rawResponse: inputData
    }
  }];
}
